require_once '../includes/auth.php';require_once '../includes/functions.php';requireActiveUser();requireTenantContext();requireModulePermission('network','edit');global $conn;
$id=(int)($_GET['id']??0);if(!$id)die('Invalid router.');$cols=[];$res=$conn->query("SHOW COLUMNS FROM mikrotik_routers");if(!$res)die('Unable to read MikroTik router configuration.');while($row=$res->fetch_assoc())$cols[]=$row['Field'];$has=fn($c)=>in_array($c,$cols,true);$tenantId=(int)getCurrentTenantId();if($tenantId<=0||!$has('tenant_id')){http_response_code(503);die('Tenant-scoped router access is unavailable for this session or database schema.');}$where='id = ? AND tenant_id = ?';$params=[$id,$tenantId];$types='ii';$stmt=$conn->prepare("SELECT * FROM mikrotik_routers WHERE $where LIMIT 1");$stmt->bind_param($types,...$params);$stmt->execute();$router=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$router)die('Router not found.');
