if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf();$hotspotLoginUrl=trim($_POST['hotspot_login_url']??'');if($hotspotLoginUrl!==''&&!filter_var($hotspotLoginUrl,FILTER_VALIDATE_URL))$errors[]='Hotspot login URL must be a valid URL.';$fields=[];$vals=[];$types='';$map=['name'=>trim($_POST['name']??''),'router_name'=>trim($_POST['name']??''),'host'=>trim($_POST['host']??$host),'ip_address'=>trim($_POST['host']??$host),'ip'=>trim($_POST['host']??$host),'username'=>trim($_POST['username']??''),'api_port'=>(int)($_POST['api_port']??$port),'port'=>(int)($_POST['api_port']??$port),'hotspot_login_url'=>$hotspotLoginUrl,'status'=>$_POST['status']??'active','description'=>trim($_POST['description']??'')];foreach($map as $c=>$v)if($has($c)){$fields[]=$c.' = ?';$vals[]=$v;$types.=is_int($v)?'i':'s';}if($has('password')&&trim($_POST['password']??'')!==''){$fields[]='password = ?';$vals[]=trim($_POST['password']);$types.='s';}if(!$errors&&$fields){$vals[]=$id;$types.='i';$sql="UPDATE mikrotik_routers SET ".implode(',',$fields)." WHERE id = ?";$sql.=' AND tenant_id = ?';$vals[]=$tenantId;$types.='i';$u=$conn->prepare($sql);if($u){$u->bind_param($types,...$vals);if($u->execute())redirect('index.php');$errors[]=$u->error;$u->close();}}}
